draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw dog
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 100, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 130, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 70, H/2 + 30);
  ctx.stroke();

  // draw baby
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 100, H/2 + 40);
  ctx.stroke();

  // dog's jealous expression
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 30, 10, 0, Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 90, H/2 - 30, 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 110, H/2 - 30, 5, 0, 2 * Math.PI);
  ctx.stroke();

  // dog looks at baby
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 20);
  ctx.lineTo(W/2 + 90 + 20 * Math.sin(t), H/2 - 10);
  ctx.stroke();

  ctx.restore();
}
